# Substitutions

Stock is checked when the order is packed. A store picker replaces an out-of-stock item unless the shopper said no.
The order page shows each line as Packed, Substituted with <item>, or Not available.

| ID    | Requirement                                                                                                                       |
| ----- | --------------------------------------------------------------------------------------------------------------------------------- |
| SUB-1 | Every new basket line starts with "Allow substitutes" switched on.                                                                |
| SUB-2 | If the shopper switches "Allow substitutes" off, the line is never substituted, chilled items included. It shows "Not available". |
| SUB-3 | A substitute is from the same category as the item it replaces.                                                                   |
| SUB-4 | A substitute never contains an allergen the shopper declared.                                                                     |
| SUB-5 | A substitute costs at most 15% more than the item it replaces.                                                                    |
| SUB-6 | A substitute is in stock.                                                                                                         |
| SUB-7 | "Suggest replacements" on an out-of-stock line shows at most 3 suggestions, and each one follows SUB-3 to SUB-6.                  |
# Basket: test plan

**Seed:** `tests/seed.spec.ts` (fresh data, Ana signed in, an empty basket)
**Source:** `world/requirements/basket.md`

### 1. Lines and quantities

#### 1.1 Adding the same item twice raises its quantity

**Covers:** BASK-1, BASK-9
**Kind:** happy

**Steps:**

1. Add Penne 500 g twice.

**Expected:**

- The header shows 1 line.
- The basket shows quantity 2 and $1.90.

#### 1.2 The quantity box changes a line

**Covers:** BASK-2
**Kind:** happy

**Steps:**

1. Add Penne 500 g.
2. Type 4 in its quantity box and press Update.

**Expected:**

- The line total is $3.80.

#### 1.3 Removing the last unit removes the line

**Covers:** BASK-3, BASK-9
**Kind:** boundary

**Steps:**

1. Add Penne 500 g.
2. Press the minus button on its line.

**Expected:**

- No line is left, the basket says it is empty, and the header shows 0.

#### 1.4 750 g of bananas at $1.39 per kg costs $1.04

**Covers:** BASK-4
**Kind:** boundary

**Steps:**

1. Add Bananas, loose with weight 750 g.

**Expected:**

- The line shows 750 g and $1.04 (0.75 x 1.39 = 1.0425, rounded once).

### 2. Offers, voucher and minimum

#### 2.1 The third yoghurt in a 3 for 2 is free

**Covers:** BASK-6
**Kind:** boundary

**Steps:**

1. Add Natural yoghurt 500 g and set the quantity to 3.

**Expected:**

- Subtotal $4.47 and Offers -$1.49.

#### 2.2 The SAVE10 voucher skips 3 for 2 lines

**Covers:** BASK-7
**Kind:** negative

**Steps:**

1. Add three Natural yoghurt 500 g and one Sourdough loaf.
2. Apply voucher SAVE10.

**Expected:**

- Voucher -$0.33: 10% of the sourdough only.

#### 2.3 The total adds delivery and takes off offers and voucher

**Covers:** BASK-5, BASK-7
**Kind:** happy

**Steps:**

1. Add three Greek yoghurt 500 g and five Ground coffee 227 g.
2. Book Mar 12 17:00 ($4.99) and apply save10 in lower case.

**Expected:**

- Total $29.77: 29.32 subtotal, -2.29 offer, -2.25 voucher, +4.99 delivery.

#### 2.4 Checkout closes again when the basket drops below $25.00

**Covers:** BASK-8
**Kind:** boundary

**Steps:**

1. Book a slot. Add six Ground coffee 227 g ($26.94).
2. Press the minus button once ($22.45).

**Expected:**

- Checkout is enabled at $26.94, then disabled, with "Spend $2.55 more to check out".
// spec: specs/basket.md
// seed: tests/seed.spec.ts
import { expect, type Page, test } from "@playwright/test";

test.beforeEach(async ({ page, request }) => {
  await request.post("/__test/reset");
  await page.goto("/signin");
  await page.getByLabel("Email").fill("ana@pantryrun.test");
  await page.getByLabel("Password").fill("pantry");
  await page.getByRole("button", { name: "Sign in" }).click();
  await expect(page.getByText("Signed in as Ana Torres")).toBeVisible();
});

async function addItem(page: Page, name: string, weight?: string) {
  await page.goto("/");
  const card = page.getByRole("article", { name, exact: true });
  if (weight) await card.getByLabel(`Weight of ${name}`).selectOption({ label: weight });
  await card.getByRole("button", { name: "Add" }).click();
  await expect(page.getByRole("status")).toHaveText(`Added ${name} to your basket`);
}

async function setQuantity(page: Page, name: string, quantity: number) {
  await page.goto("/basket");
  await page.getByLabel(`Quantity of ${name}`).fill(String(quantity));
  await page.getByRole("button", { name: `Update ${name}` }).click();
}

const lineTotal = (page: Page, name: string) =>
  page.getByTestId("basket-line").filter({ hasText: name }).getByTestId("line-total");

test.describe("Lines and quantities", () => {
  test("Adding the same item twice raises its quantity", async ({ page }) => {
    await addItem(page, "Penne 500 g");
    await addItem(page, "Penne 500 g");
    await expect(page.getByTestId("basket-count")).toHaveText("1");
    await page.goto("/basket");
    await expect(page.getByLabel("Quantity of Penne 500 g")).toHaveValue("2");
    await expect(lineTotal(page, "Penne 500 g")).toHaveText("$1.90");
  });

  test("The quantity box changes a line", async ({ page }) => {
    await addItem(page, "Penne 500 g");
    await setQuantity(page, "Penne 500 g", 4);
    await expect(lineTotal(page, "Penne 500 g")).toHaveText("$3.80");
  });

  test("Removing the last unit removes the line", async ({ page }) => {
    await addItem(page, "Penne 500 g");
    await page.goto("/basket");
    await page.getByRole("button", { name: "Remove one Penne 500 g" }).click();
    await expect(page.getByTestId("basket-line")).toHaveCount(0);
    await expect(page.getByTestId("empty-basket")).toBeVisible();
    await expect(page.getByTestId("basket-count")).toHaveText("0");
  });

  test("750 g of bananas at $1.39 per kg costs $1.04", async ({ page }) => {
    await addItem(page, "Bananas, loose", "750 g");
    await page.goto("/basket");
    await expect(page.getByTestId("line-weight")).toHaveText("750 g");
    await expect(lineTotal(page, "Bananas, loose")).toHaveText("$1.04");
  });
});

test.describe("Offers, voucher and minimum", () => {
  test("The third yoghurt in a 3 for 2 is free", async ({ page }) => {
    await addItem(page, "Natural yoghurt 500 g");
    await setQuantity(page, "Natural yoghurt 500 g", 3);
    await expect(page.getByTestId("subtotal")).toHaveText("$4.47");
    await expect(page.getByTestId("offers")).toHaveText("-$1.49");
  });

  test("The SAVE10 voucher skips 3 for 2 lines", async ({ page }) => {
    await addItem(page, "Natural yoghurt 500 g");
    await setQuantity(page, "Natural yoghurt 500 g", 3);
    await addItem(page, "Sourdough loaf");
    await page.goto("/basket");
    await page.getByLabel("Voucher code").fill("SAVE10");
    await page.getByRole("button", { name: "Apply" }).click();
    await expect(page.getByTestId("voucher")).toHaveText("-$0.33");
  });

  test("The total adds delivery and takes off offers and voucher", async ({ page }) => {
    await addItem(page, "Greek yoghurt 500 g");
    await setQuantity(page, "Greek yoghurt 500 g", 3);
    await addItem(page, "Ground coffee 227 g");
    await setQuantity(page, "Ground coffee 227 g", 5);
    await page.goto("/slots");
    await page.getByRole("radio", { name: /Mar 12 17:00 to 18:00/ }).check();
    await page.getByRole("button", { name: "Book slot" }).click();
    await expect(page).toHaveURL(/\/basket/);
    await page.getByLabel("Voucher code").fill("save10");
    await page.getByRole("button", { name: "Apply" }).click();
    await expect(page.getByTestId("total")).toHaveText("$29.77");
  });

  test("Checkout closes again when the basket drops below $25.00", async ({ page }) => {
    await page.goto("/slots");
    await page.getByRole("radio", { name: /Mar 12 09:00/ }).check();
    await page.getByRole("button", { name: "Book slot" }).click();
    await expect(page).toHaveURL(/\/basket/);
    await addItem(page, "Ground coffee 227 g");
    await setQuantity(page, "Ground coffee 227 g", 6);
    await expect(page.getByRole("button", { name: "Checkout" })).toBeEnabled();
    await page.getByRole("button", { name: "Remove one Ground coffee 227 g" }).click();
    await expect(page.getByRole("button", { name: "Checkout" })).toBeDisabled();
    await expect(page.getByTestId("checkout-blocked")).toContainText(
      "Spend $2.55 more to check out",
    );
  });
});
