289	// Applies one change to the basket lines. Returns false when the action is not one we know.
290	function changeLines(
291	  basket: store.Basket,
292	  product: Product,
293	  action: string,
294	  form: Record<string, unknown>,
295	): boolean {
296	  if (action === "decrement") basket.lines = removeOne(basket.lines, product);
297	  else if (action === "remove") {
298	    basket.lines = basket.lines.filter((line) => line.sku !== product.sku);
299	  } else if (action === "qty") basket.lines = setQuantity(basket.lines, product, Number(form.qty));
300	  else if (action === "substitutes") {
301	    const line = basket.lines.find((candidate) => candidate.sku === product.sku);
302	    if (line) line.substitutes = form.allow === "yes";
303	  } else return false;
304	  return true;
305	}
